function fieldsFor(p){if(SCHEMAS[p])return SCHEMAS[p];if(['Cio','Gestação','Maternidade','Pré-creche','Creche','Desmame','Recria','AVA','Terminação'].includes(p))return [F.text('ID animal / lote',true),F.date('Data do manejo'),F.number('Quantidade de animais'),F.number('Peso médio (kg)'),F.text('Instalação'),...COMMON.slice(2)];if(p.includes('Compra')||p.includes('Contas')||p.includes('Vendas')||p==='Pedidos'||p==='Fluxo de caixa')return [F.text('Descrição',true),F.text('Fornecedor / cliente'),F.number('Quantidade'),F.number('Valor (R$)'),F.date('Data'),F.text('Centro de custo'),F.text('Responsável'),F.area('Observações')];return [F.text('Descrição / código',true),F.text('Granja / setor'),F.text('Animal ou lote vinculado'),F.date('Data'),F.number('Quantidade / valor'),F.text('Responsável'),F.area('Observações')]}
function columnsFor(p){const f=fieldsFor(p);return f.slice(0,Math.min(4,f.length)).map(x=>x.label)}
function countPending(){return data.pending.length}
